document.querySelectorAll('[data-lens]').forEach((lens)=>{const title=lens.querySelector('[data-lens-title]');const copy=lens.querySelector('[data-lens-copy]');const buttons=[...lens.querySelectorAll('[data-title]')];buttons.forEach((button)=>button.addEventListener('click',()=>{buttons.forEach((item)=>{item.classList.toggle('active',item===button);item.setAttribute('aria-selected',String(item===button));});title.textContent=button.dataset.title;copy.textContent=button.dataset.copy;}));});
